//! Issue 2 re-check (item A) regression harness: the GEV CP upper tail must NOT
//! be clamped to the ML upper endpoint.
//!
//! Loads `tests/golden/gev_tail_golden.json` (generated by
//! `tools/generate_gev_tail_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and checks that the Rust [`predict_gev`] CP
//! quantiles match the reference **unclamped** `qgev_cp` output, including the
//! 1-in-1000 return level (`p = 0.999`).
//!
//! # The regression (item A)
//!
//! An earlier Rust revision clamped the CP quantiles to the ML upper endpoint
//! `ml_max` (and to the `fixgevrange` support bound). The reference `qgev_cp`
//! does **not** clamp `rh_flat_quantiles`: it only uses `ml_max` to report the
//! bound and to build the quantile-derived density. The clamp biased the upper
//! tail low (1-in-1000: reference ~4.287 vs clamped ~2.769 in the report's
//! dataset). This harness pins the reference unclamped values so the clamp
//! cannot be reintroduced.
//!
//! # What is compared
//!
//! - **CP quantiles** (`cp_quantiles`): the Rust `predict_gev` CP quantiles
//!   (DMGS expansion + monotone guard, **no** support clamp) vs. the reference
//!   `qgev_cp`'s unclamped `rh_flat_quantiles`.
//! - **`ml_max`** and **`revert2ml`**: exact-match fields (§7.2).
//! - **The 1-in-1000 return level** (`p = 0.999`): must be finite, must exceed
//!   `ml_max` (the reference CP tail is above the ML upper endpoint), and must
//!   match the reference value.
//!
//! # Tolerance policy (§7.2)
//!
//! The consolidated, canonical tolerance policy lives in
//! [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md). The GEV CP
//! quantiles use `rtol = 1e-3` (the Rust GEV keeps the numerical
//! third-derivative fallback, so the DMGS bias-correction term carries
//! finite-difference error; see §3.6). The optimizer-produced `ml_params` use
//! `rtol = 1e-4` (§3.2).

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::api::{predict_gev, PredictionRequest};
use fitdistcp_core::models::GenExtreme;

/// Tolerance for the GEV CP quantiles (numerical third derivatives, §3.6).
const CPQ_RTOL: f64 = 1e-3;
const CPQ_ATOL: f64 = 1e-8;

/// Tolerance for the optimizer-produced `ml_params` (§3.2).
const OPT_RTOL: f64 = 1e-4;
const OPT_ATOL: f64 = 1e-6;

/// The reference `fdalpha` default for the quantile-derived density.
const FDALPHA: f64 = 0.01;

/// The 1-in-1000 return level is the last `p` in the grid (`p = 0.999`).
const P_1IN1000_IDX: usize = 6;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_bool(&self) -> bool {
        match self {
            Json::Bool(b) => *b,
            other => panic!("expected bool, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'u' => {
                            let hex = std::str::from_utf8(&self.bytes[self.pos + 1..self.pos + 5])
                                .expect("utf8 hex");
                            let code = u32::from_str_radix(hex, 16).expect("hex");
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            self.pos += 4;
                        }
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "gev_tail_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

/// Run `predict_gev` on the fixture dataset and return the [`FitResult`].
fn run_predict_gev(y: &[f64], p_grid: &[f64]) -> fitdistcp_core::api::FitResult {
    let req = PredictionRequest {
        y: y.to_vec(),
        x: vec![1.0, 1.3, 1.6, 1.9, 2.2],
        p: p_grid.to_vec(),
        t: None,
        t0: None,
        n0: None,
        means: None,
    };
    // The reference `gev_setics` seeds the optimizer; the Rust `fit` uses the
    // same heuristic internally, so a generic init is fine here.
    predict_gev(GenExtreme, &req, &[1.4, 0.3, -0.1], FDALPHA)
}

/// The Rust CP quantiles must match the reference **unclamped** values, and the
/// 1-in-1000 return level must exceed `ml_max` (the clamp would pin it to the
/// bound).
#[test]
fn golden_gev_cp_tail_is_not_clamped_to_ml_max() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();
    assert_eq!(p_grid.len(), 7, "p_grid must include the 1-in-1000 level");
    assert_close(p_grid[P_1IN1000_IDX], 0.999, 1e-12, 1e-12, "p_grid[6]");

    let y = datasets.get("y_tail").as_f64_vec();
    assert_eq!(y.len(), 20, "fixture must have n = 20");
    let m = models.get("gev_tail");

    let r = run_predict_gev(&y, &p_grid);

    // The fitted shape must be negative (finite upper support bound).
    assert!(
        r.ml_params[2] < 0.0,
        "expected negative shape, got {}",
        r.ml_params[2]
    );

    // The Rust MLE should match the reference MLE (optimizer tolerance).
    let ref_params = m.get("params").as_f64_vec();
    assert_close(r.ml_params[0], ref_params[0], OPT_RTOL, OPT_ATOL, "loc");
    assert_close(r.ml_params[1], ref_params[1], OPT_RTOL, OPT_ATOL, "scale");
    assert_close(r.ml_params[2], ref_params[2], OPT_RTOL, OPT_ATOL, "shape");

    // revert2ml is an exact-match field (§7.2).
    let ref_revert = m.get("revert2ml").as_bool();
    assert_eq!(
        GenExtreme.revert2ml(r.ml_params[2]),
        ref_revert,
        "revert2ml mismatch"
    );
    assert!(!ref_revert, "fixture should be in the DMGS regime");

    // ml_max is an exact-match field: loc - scale/shape for negative shape.
    let ref_ml_max = m.get("ml_max").as_f64();
    let ml_max = GenExtreme.ml_max(r.ml_params[0], r.ml_params[1], r.ml_params[2]);
    assert_close(ml_max, ref_ml_max, 1e-6, 1e-8, "ml_max");

    // CP quantiles (DMGS + monotone guard, NO support clamp) vs. the reference
    // unclamped `rh_flat_quantiles`.
    compare_vec(
        &r.cp_quantiles,
        &m.get("cp_quantiles").as_f64_vec(),
        CPQ_RTOL,
        CPQ_ATOL,
        "gev_tail.cp_quantiles",
    );

    // The 1-in-1000 return level must be finite and must exceed `ml_max`: the
    // reference CP tail is above the ML upper endpoint, so a clamp to `ml_max`
    // would be a regression (item A).
    let q1000 = r.cp_quantiles[P_1IN1000_IDX];
    assert!(
        q1000.is_finite(),
        "1-in-1000 CP quantile = {q1000} not finite"
    );
    assert!(
        q1000 > ml_max,
        "1-in-1000 CP quantile = {q1000} must exceed ml_max = {ml_max} \
         (a clamp to ml_max is the item-A regression)"
    );

    // The reference value itself must exceed `ml_max` (sanity check on the
    // fixture: it genuinely exercises the unclamped tail).
    let ref_q1000 = m.get("cp_quantiles").as_f64_vec()[P_1IN1000_IDX];
    assert!(
        ref_q1000 > ref_ml_max,
        "fixture must have a reference 1-in-1000 CP quantile above ml_max: \
         ref = {ref_q1000}, ml_max = {ref_ml_max}"
    );

    // The CP quantiles remain non-decreasing in `p` (the monotone guard is
    // retained; item A only removes the support clamp).
    assert!(
        r.cp_quantiles.windows(2).all(|w| w[0] <= w[1]),
        "CP quantiles must be non-decreasing in p, got {:?}",
        r.cp_quantiles
    );
}
